{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "A radiolabeled tryptophan analogue with the same amino-acid/carboxylic acid core and indole system showed low brain uptake in mice, directly supporting poor CNS access for the query's tryptophan-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Another tryptophan-derived amino acid with a free carboxylic acid, 5-[18F]FEHTrp, showed low brain uptake (0.84 %ID/g) in mice, indicating that this structural class does not achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "The closely related tryptophan analogue [18F]FPOTrp also showed low brain uptake (1.16 %ID/g), reinforcing the poor CNS penetration pattern for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "An N-aroyl amide with polar substituents, MBDA, had very low brain uptake (0.06 %/g) in rats, supporting that N-acylated polar aromatic structures do not confer meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tarenflurbil, a carboxylic acid-containing aromatic drug, showed a CSF/plasma ratio of only 1.3% in rodents, demonstrating that acidic molecules with substantial hydrophobic character can still have inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "An amide-rich molecule, Merck-3, was undetectable in brain after intravenous dosing and was identified as a P-glycoprotein substrate, supporting efflux liability for amide-containing structures.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a polar, acidic tryptophan/oxindole amide derivative. All highly transferable experimental evidence from tryptophan analogues, N-aroyl amides, and carboxylic acid-containing CNS-poor drugs points to inadequate blood-brain barrier penetration, with no positive CNS exposure evidence to override this pattern.",
  "evidence_gaps": [
    "No direct brain or CSF concentration measurement for the exact query molecule.",
    "No human pharmacokinetic or CNS exposure data for the query.",
    "No explicit transporter assay for the query, though related amide-rich structures show P-gp efflux liability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

